package com.nigson.experience.files;

import java.sql.Timestamp;
import java.time.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;

public final class JdbcFileRepository implements FileRepository {
    private final JdbcTemplate jdbc; private final Clock clock;
    public JdbcFileRepository(JdbcTemplate jdbc,Clock clock){this.jdbc=jdbc;this.clock=clock;}
    private static Timestamp ts(Instant i){return i==null?null:Timestamp.from(i);}
    private Stored map(java.util.Map<String,Object> r){return new Stored((UUID)r.get("id"),(UUID)r.get("owner_party_id"),(UUID)r.get("organization_id"),(String)r.get("object_key"),(String)r.get("purpose"),(String)r.get("mime_type"),((Number)r.get("byte_size")).longValue(),((String)r.get("checksum_sha256")).trim(),(String)r.get("classification"),(String)r.get("scan_status"),((Number)r.get("version")).longValue(),(String)r.get("source_key"),(String)r.get("final_key"),((Timestamp)r.get("upload_expires_at")).toInstant(),(UUID)r.get("scan_command_id"),(String)r.get("source_version"),(String)r.get("source_etag"),(String)r.get("transfer_state"),r.get("copy_lease_until")==null?null:((Timestamp)r.get("copy_lease_until")).toInstant(),(String)r.get("scan_request_hash"),(String)r.get("scan_result"),(String)r.get("scanner_version"));}
    private static final String SELECT="SELECT a.id,a.owner_party_id,a.organization_id,a.object_key,a.purpose,a.mime_type,a.byte_size,a.checksum_sha256,a.classification,a.scan_status,a.version,t.source_key,t.final_key,t.upload_expires_at,t.scan_command_id,t.source_version,t.source_etag,t.state AS transfer_state,t.copy_lease_until,t.scan_request_hash,t.scan_result,t.scanner_version FROM experience.file_asset a JOIN experience.file_transfer t ON t.id=a.id WHERE a.id=?";
    public Stored find(UUID id,boolean lock){var rows=jdbc.queryForList(SELECT+(lock?" FOR UPDATE OF a,t":""),id);if(rows.size()!=1)throw new com.nigson.shared.problem.Problem.Failure(com.nigson.shared.problem.ProblemCode.NOT_FOUND);return map(rows.getFirst());}
    public Stored create(UUID id,UUID owner,UUID organization,FileValues.Upload in,String source,String target,Instant expiry,String actor){Instant now=clock.instant();String classification=in.purpose().equals("DISTRIBUTOR_PROOF")?"PRIVATE":"PUBLIC";jdbc.update("INSERT INTO experience.file_asset(id,created_by,updated_by,owner_party_id,organization_id,object_key,purpose,mime_type,byte_size,checksum_sha256,classification,scan_status,linked_resource_type,linked_resource_id) VALUES (?,?,?,?,?,?,?,?,?,?,?,'UPLOADING',?,?)",id,actor,actor,owner,organization,source,in.purpose(),in.mimeType(),in.size(),in.checksumSha256(),classification,in.linkedResourceId()==null?null:(in.purpose().equals("DISTRIBUTOR_PROOF")?"DISTRIBUTOR_APPLICATION":"CONTENT_ITEM"),in.linkedResourceId());jdbc.update("INSERT INTO experience.file_transfer(id,created_by,updated_by,owner_party_id,source_key,final_key,upload_expires_at) VALUES (?,?,?,?,?,?,?)",id,actor,actor,owner,source,target,ts(expiry));return find(id,false);}
    public Stored quarantined(Stored b,FileStorage.ObjectInfo info,UUID command,String actor){Instant now=clock.instant();jdbc.update("UPDATE experience.file_asset SET scan_status='QUARANTINED',version=version+1,updated_at=?,updated_by=? WHERE id=?",ts(now),actor,b.id());jdbc.update("UPDATE experience.file_transfer SET state='QUARANTINED',scan_command_id=?,source_version=?,source_etag=?,version=version+1,updated_at=?,updated_by=? WHERE id=? AND state='UPLOADING'",command,info.version(),info.etag(),ts(now),actor,b.id());return find(b.id(),false);}
    public Stored claim(Stored b,FileValues.Scan scan,String hash,Instant lease,String actor){Instant now=clock.instant();jdbc.update("UPDATE experience.file_transfer SET state='COPYING',scan_request_hash=?,scan_result=?,scanner_version=?,copy_lease_until=?,version=version+1,updated_at=?,updated_by=? WHERE id=?",hash,scan.result(),scan.scannerVersion(),ts(lease),ts(now),actor,b.id());return find(b.id(),false);}
    public Stored unknown(Stored b,String hash,String actor){Instant now=clock.instant();jdbc.update("UPDATE experience.file_transfer SET state='UNKNOWN',scan_request_hash=?,copy_lease_until=NULL,version=version+1,updated_at=?,updated_by=? WHERE id=?",hash,ts(now),actor,b.id());return find(b.id(),false);}
    public Stored finish(Stored b,String result,String hash,String scanner,String actor){Instant now=clock.instant();String status=result.equals("CLEAN")?"CLEAN":"REJECTED";jdbc.update("UPDATE experience.file_asset SET scan_status=?,object_key=?,scan_result=?,version=version+1,updated_at=?,updated_by=? WHERE id=?",status,result.equals("CLEAN")?b.finalKey():b.key(),result,ts(now),actor,b.id());jdbc.update("UPDATE experience.file_transfer SET state=?,scan_request_hash=?,scan_result=?,scanner_version=?,copy_lease_until=NULL,version=version+1,updated_at=?,updated_by=? WHERE id=?",status,hash,result,scanner,ts(now),actor,b.id());return find(b.id(),false);}
}
